#include <print>
#include <queue>
#include <vector>
#include <functional>

int merge_cost() {
    std::priority_queue<int, std::vector<int>, std::greater<int>> need;
    for (int v : {1, 2, 3, 4}) need.push(v);
    int total = 0;
    while (need.size() > 1) {
        int a = need.top(); need.pop();
        int b = need.top(); need.pop();
        total += a + b;
        std::println("本次代价 {}", a + b);
        need.push(a + b);
    }
    return total;
}

int main() {
    std::println("总代价 {}", merge_cost());
    std::priority_queue<int, std::vector<int>, std::greater<int>> top3;
    for (int score : {88, 95, 72, 91, 60, 83}) {
        top3.push(score);
        if (top3.size() > 3) top3.pop();
    }
    std::print("前三名从小到大弹出: ");
    while (!top3.empty()) { std::print("{} ", top3.top()); top3.pop(); }
    std::println("");
    return 0;
}

